#include "Animation/ModelSkeleton.h"
#include "Assets/AssetManager.h"
#include "Animation/AvatarSystem.h"
namespace Stardust {
bool ModelSkeleton::Import(Scene& scene,EntityID root,const std::string& asset){if(scene.Reg().Has<FbxRigComponent>(root))return false;auto bones=AssetManager::GetFbxSkeleton(asset);if(bones.empty())return false;auto rootWorld=scene.GetWorldMatrix(root);u64 uuid=scene.Reg().Get<IDComponent>(root).uuid;std::vector<EntityID> entities;for(auto& bone:bones){auto child=scene.CreateEntity(bone.name);scene.SetParent(child,bone.parent<0?root:entities[bone.parent],false);scene.SetWorldMatrix(child,rootWorld*bone.world);scene.Reg().Add<BoneComponent>(child)=BoneComponent{uuid,bone.nodeId};entities.push_back(child);}scene.Reg().Add<FbxRigComponent>(root).source=asset;if(!scene.Reg().Has<AnimatorComponent>(root))scene.Reg().Add<AnimatorComponent>(root);auto settings=FbxImportSettings::Load(asset);if(settings.animationType==FbxImportSettings::Humanoid)scene.Reg().Get<AnimatorComponent>(root).avatar=settings.avatar;return true;}
void ModelSkeleton::ApplyPose(Scene& scene,EntityID root,float time,const std::string& take){auto* rig=scene.Reg().TryGet<FbxRigComponent>(root);if(!rig)return;auto bones=AssetManager::GetFbxSkeleton(rig->source,std::floor(time*30)/30,take);std::unordered_map<u32,glm::mat4> matrices;for(auto& bone:bones)matrices[bone.nodeId]=bone.local;auto uuid=scene.Reg().Get<IDComponent>(root).uuid;scene.Reg().Each<BoneComponent>([&](EntityID e,BoneComponent& bone){if(bone.root!=uuid||!matrices.contains(bone.nodeId))return;auto parent=scene.GetParent(e);scene.SetWorldMatrix(e,(parent?scene.GetWorldMatrix(parent):glm::mat4(1))*matrices[bone.nodeId]);});}
std::unordered_map<u32,glm::mat4> ModelSkeleton::Pose(Scene& scene,EntityID root){std::unordered_map<u32,glm::mat4> pose;auto uuid=scene.Reg().Get<IDComponent>(root).uuid;auto inverse=glm::inverse(scene.GetWorldMatrix(root));scene.Reg().Each<BoneComponent>([&](EntityID e,BoneComponent& bone){if(bone.root==uuid)pose[bone.nodeId]=inverse*scene.GetWorldMatrix(e);});return pose;}
}
